    Route::get('/categories/{category}/block-image', [CategoryController::class, 'blockImage'])->whereNumber('category')->name('categories.block-image');
    Route::get('/categories/{category}/menu-icon', [CategoryController::class, 'menuIcon'])->whereNumber('category')->name('categories.menu-icon');
    Route::get('/categories/{category}/banner-image', [CategoryController::class, 'bannerImage'])->whereNumber('category')->name('categories.banner-image');
    Route::delete('/categories/bulk', [CategoryController::class, 'bulkDestroy'])->name('categories.bulk-destroy');
    Route::resource('categories', CategoryController::class)->except('show')->whereNumber('category');
});
